begin;
-- Sourced catalogue entries only: no patient, inventory or financial seed records.
-- Pediatric and emergency entries intentionally have no automatic dose/frequency.
alter table public.dental_medicine_references drop constraint dental_medicine_references_frequency_check;
alter table public.dental_medicine_references add constraint dental_medicine_references_frequency_check check(frequency in ('','OD','BID','TID','QID','PRN','STAT'));
alter table public.clinic_medicines drop constraint clinic_medicines_frequency_check;
alter table public.clinic_medicines add constraint clinic_medicines_frequency_check check(frequency in ('','OD','BID','TID','QID','PRN','STAT'));
update public.dental_medicine_references set instructions='Take with or without food. Swallow with water. Avoid other medicines containing paracetamol.',reviewed_on='2026-09-12' where code='paracetamol-500';
update public.dental_medicine_references set instructions='Take with or after food. Swallow whole; do not crush or chew. Avoid other NSAIDs.',reviewed_on='2026-09-12' where code='diclofenac-50';
update public.dental_medicine_references set instructions='Take with or without food. Swallow whole with water and space doses evenly. Follow the prescribed course and review.',reviewed_on='2026-09-12' where code='amoxicillin-500';
update public.dental_medicine_references set instructions='Take with or just after food. Swallow whole. Avoid alcohol during treatment and for 48 hours after the last dose.',reviewed_on='2026-09-12' where code='metronidazole-400';
-- Supplementary administration sources (original dose references remain attached):
-- https://www.nhs.uk/medicines/paracetamol-for-adults/
-- https://www.nhs.uk/medicines/diclofenac/how-and-when-to-take-or-use-diclofenac/
-- https://www.nhs.uk/medicines/amoxicillin/how-and-when-to-take-amoxicillin/
-- https://www.nhs.uk/medicines/metronidazole/how-and-when-to-take-or-use-metronidazole/
-- https://www.nhs.uk/medicines/domperidone/how-and-when-to-take-domperidone/
commit;
